import {ToolRegistry} from './registry.js';

describe('Dynamic schema cache [specs/hal-engine-tool-input-validation/spec.md#9]', () => {
  it('reuses a dynamic schema without reading it again during compilation', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const inputSchema = {
      get "'$id() {
        schemaReads += 1;
        return '"'https://example.com/weather';
      },
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    registry.register(
      () => ({name: 'weather', description: 'Weather forecast', inputSchema}),
      async input => JSON.stringify(input)
    );
    await registry.execute('weather', {location: 'Berlin'});
    const compiledReads = schemaReads;
    const response = await registry.execute('weather', {});

    expect({schemaReads, result: response.result}).toEqual({
      schemaReads: compiledReads,
      result: expect.stringMatching(/required.*location|location.*required/),
    });
  });
});
EOF
